/**
 * @name Command injection via subprocess
 * @description Using subprocess with user-controlled input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-dotenv
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources are file content reads or external input
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("io").getMember("open").getACall() or
      call = API::builtin("open").getACall()
    |
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "file input"

/**
 * @name Path traversal in file operations
 * @description Using user-controlled input to construct file paths can allow path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-dotenv
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.dataflow.new.RemoteFlowSources

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in ["dotenv_path", "path", "filename", "stream_path"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Unsafe file write operations
 * @description Writing to user-controlled file paths without validation can overwrite sensitive files
 * @kind path-problem
 * @problem.severity high
 * @id py/unsafe-file-write-dotenv
 * @tags security
 *        external/cwe/cwe-073
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeFileWriteConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // CLI arguments as sources
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("click").getMember(["argument", "option"]).getACall()
    |
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File write operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      exists(DataFlow::Node mode |
        mode = call.getArg(1) or
        mode = call.getArgByName("mode")
      |
        mode.asExpr().(StringLiteral).getText().matches("%w%")
      )
    |
      sink = call.getArg(0)
    )
  }
}

module UnsafeFileWriteFlow = TaintTracking::Global<UnsafeFileWriteConfig>;
import UnsafeFileWriteFlow::PathGraph

from UnsafeFileWriteFlow::PathNode source, UnsafeFileWriteFlow::PathNode sink
where UnsafeFileWriteFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe file write from $@.", source.getNode(), "user input"
